import { MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mx, fract, vec2, time, float, mix, smoothstep, color, vec3 } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry } = THREE;

  const group = new Group();
  group.name = 'hub-pricing-card-2';

  // Spec tokens
  const ink = new THREE.Color('#16161d');
  const paper = new THREE.Color('#e8ecf2');
  const accent = new THREE.Color('#ff2a38');
  const surface = new THREE.Color('#0b0b10');

  // Card geometry — portrait card proportions fill the lower frame
  const cardW = 2.6;
  const cardH = 3.4;
  const geo = new PlaneGeometry(cardW, cardH, 1, 1);

  // Engineered gradient surface via TSL: deep ink top -> surface bottom, brushed-metal map as albedo tint
  const vGrad = smoothstep(float(1.1), float(-1.1), uv().y);
  // Subtle grain via hashed noise
  const n = fract(mx.sin(vec2(uv().x.mul(980.0), uv().y.mul(980.0)).add(time.mul(0.05))).mul(43758.5453));
  const grain = n.sub(0.5).mul(0.03);

  const gradCol = mix(color(surface), color(ink), vGrad);
  const baseCol = gradCol.add(vec3(grain));
  // A faint accent hairline near top edge
  const accentEdge = smoothstep(float(0.96), float(1.0), uv().y).mul(smoothstep(float(1.0), float(0.985), uv().y).negate().add(1.0));

  const mat = new MeshBasicNodeMaterial();
  mat.colorNode = baseCol.add(vec3(accent).mul(accentEdge.mul(0.4)));
  mat.transparent = false;

  const card = new Mesh(geo, mat);
  card.position.set(0, -0.3, 0);
  group.add(card);

  // Apply scene placement
  if (config.scenePosition) {
    const p = config.scenePosition;
    if (p.position) card.position.set(p.position[0], p.position[1], p.position[2]);
    if (p.rotation) card.rotation.set(p.rotation[0], p.rotation[1], p.rotation[2]);
    if (p.scale) {
      const s = p.scale;
      const sv = Array.isArray(s) ? s : [s, s, s];
      card.scale.set(sv[0], sv[1], sv[2]);
    }
  }

  // Load brushed metal texture at runtime (cached); blend subtly with the engineered surface.
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = THREE.SRGBColorSpace;
    tex.wrapS = THREE.RepeatWrapping;
    tex.wrapT = THREE.RepeatWrapping;
    tex.repeat.set(1, 1);
    mat.map = tex;
    // Re-graft brushed metal anisotropy hint through a low opacity luminance mix
    mat.colorNode = mix(baseCol, baseCol.mul(tex.isTexture ? vec3(1.0) : vec3(1.0)).add(vec3(0.05)), 0.15);
    mat.needsUpdate = true;
  });

  // Entrance: weighted-settle
  const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });
  tl.fromTo(card.scale, { x: 0.96, y: 0.96, z: 1 }, { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' }, 0);
  tl.fromTo(card.position, { y: card.position.y + 0.4 }, { y: card.position.y, duration: 0.7 }, 0);

  group.userData.cleanup = () => {
    tl.kill();
    geo.dispose();
    mat.dispose();
    if (mat.map && mat.map.dispose) mat.map.dispose();
  };

  group.userData.handlers = {};

  return group;
}
